package net.civeira.phylax.feature.template.snippetasset.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.template.snippetasset.domain.SnippetAsset;
import net.civeira.phylax.feature.template.snippetasset.domain.event.SnippetAssetEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class SnippetAssetEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<SnippetAssetEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final SnippetAsset entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
